init_machine_mode:
                  li x10, 0x21800
                  csrw 0x300, x10 # MSTATUS
                  li x10, 0x0
                  csrw 0x304, x10 # MIE
                  li x29, 0x8ffffffc
                  li x10, 0x300
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x300
                  sw x10, 0(x29)
